drop function if exists iam.bootstrap_owner(text);

create or replace function iam.bootstrap_owner(
  p_tenant_id uuid,
  p_tenant_name text default 'My Store'
)
returns uuid
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_role text;
  v_status text;
  v_store_id uuid;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"NOT_AUTHENTICATED","message":"Not authenticated.","details":{}}';
  end if;

  if p_tenant_id is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Tenant id is required to bootstrap store.","details":{}}';
  end if;

  select m.role, m.status
  into v_role, v_status
  from iam.memberships m
  where m.tenant_id = p_tenant_id
    and m.user_id = v_user_id;

  if v_role is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"TENANT_ACCESS_DENIED","message":"Tenant access denied.","details":{}}';
  end if;

  if coalesce(v_status, 'active') = 'inactive' then
    raise exception using errcode = 'P0001',
      message = '{"code":"MEMBERSHIP_INACTIVE","message":"Membership is inactive.","details":{}}';
  end if;

  if coalesce(v_status, 'active') = 'removed' then
    raise exception using errcode = 'P0001',
      message = '{"code":"MEMBERSHIP_REMOVED","message":"Membership is removed.","details":{}}';
  end if;

  if coalesce(v_status, 'active') <> 'active' then
    raise exception using errcode = 'P0001',
      message = '{"code":"TENANT_ACCESS_DENIED","message":"Tenant access denied.","details":{}}';
  end if;

  if v_role not in ('owner', 'store_owner') then
    raise exception using errcode = 'P0001',
      message = '{"code":"PERMISSION_DENIED","message":"Only tenant owners can bootstrap stores.","details":{}}';
  end if;

  insert into iam.stores (tenant_id, code, display_name, status)
  values (
    p_tenant_id,
    'default',
    coalesce(nullif(trim(p_tenant_name), ''), 'Default Store'),
    'active'
  )
  on conflict (tenant_id, code) do update
  set display_name = excluded.display_name, status = 'active'
  returning id into v_store_id;

  insert into iam.membership_store_scopes (
    tenant_id,
    user_id,
    store_id,
    is_default
  ) values (
    p_tenant_id,
    v_user_id,
    v_store_id,
    true
  )
  on conflict (tenant_id, user_id, store_id) do update
  set is_default = true;

  return p_tenant_id;
end;
$$;

create or replace function iam.get_session_context(p_tenant_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id uuid;
  v_role text;
  v_status text;
  v_is_owner boolean;
  v_active_count int;
  v_store_ids uuid[];
  v_active_store_id uuid;
  v_active_store_code text;
  v_active_store_display_name text;
  v_permissions text[];
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"NOT_AUTHENTICATED","message":"Not authenticated.","details":{}}';
  end if;

  if p_tenant_id is not null then
    select m.tenant_id, m.role, m.status, coalesce(m.is_owner, false)
    into v_tenant_id, v_role, v_status, v_is_owner
    from iam.memberships m
    where m.user_id = v_user_id
      and m.tenant_id = p_tenant_id;

    if v_tenant_id is null then
      raise exception using errcode = 'P0001',
        message = '{"code":"TENANT_ACCESS_DENIED","message":"Tenant access denied.","details":{}}';
    end if;
    if v_status = 'inactive' then
      raise exception using errcode = 'P0001',
        message = '{"code":"MEMBERSHIP_INACTIVE","message":"Membership is inactive.","details":{}}';
    end if;
    if v_status = 'removed' then
      raise exception using errcode = 'P0001',
        message = '{"code":"MEMBERSHIP_REMOVED","message":"Membership is removed.","details":{}}';
    end if;
    if coalesce(v_status, 'active') <> 'active' then
      raise exception using errcode = 'P0001',
        message = '{"code":"TENANT_ACCESS_DENIED","message":"Tenant access denied.","details":{}}';
    end if;
  else
    select count(*)::int
    into v_active_count
    from iam.memberships m
    where m.user_id = v_user_id
      and m.status = 'active';

    -- Ambiguous / empty: caller must pick tenant explicitly (multi-tenant UX).
    if coalesce(v_active_count, 0) = 0 or v_active_count > 1 then
      return null;
    end if;

    select m.tenant_id, m.role, m.status, coalesce(m.is_owner, false)
    into v_tenant_id, v_role, v_status, v_is_owner
    from iam.memberships m
    where m.user_id = v_user_id
      and m.status = 'active'
    order by m.created_at
    limit 1;
  end if;

  select array_agg(scope.store_id)
  into v_store_ids
  from iam.membership_store_scopes scope
  join iam.stores store on store.id = scope.store_id
    and store.tenant_id = scope.tenant_id
  where scope.tenant_id = v_tenant_id
    and scope.user_id = v_user_id
    and scope.is_default
    and store.status = 'active';

  if coalesce(cardinality(v_store_ids), 0) = 0
    and v_role in ('owner', 'store_owner') then
    perform iam.bootstrap_owner(v_tenant_id, 'My Store');

    select array_agg(scope.store_id)
    into v_store_ids
    from iam.membership_store_scopes scope
    join iam.stores store on store.id = scope.store_id
      and store.tenant_id = scope.tenant_id
    where scope.tenant_id = v_tenant_id
      and scope.user_id = v_user_id
      and scope.is_default
      and store.status = 'active';
  end if;

  if coalesce(cardinality(v_store_ids), 0) <> 1 then
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Exactly one active default store is required.","details":{}}';
  end if;

  v_active_store_id := v_store_ids[1];

  select store.code, store.display_name
  into v_active_store_code, v_active_store_display_name
  from iam.stores store
  where store.tenant_id = v_tenant_id
    and store.id = v_active_store_id
    and store.status = 'active';

  if v_active_store_code is null or v_active_store_display_name is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Active store identity is required.","details":{}}';
  end if;

  if coalesce(v_is_owner, false) or v_role in ('owner', 'store_owner') then
    v_permissions := array[]::text[];
  else
    select coalesce(array_agg(rp.permission order by rp.permission), array[]::text[])
    into v_permissions
    from iam.role_permissions rp
    where rp.role = v_role;
  end if;

  return jsonb_build_object(
    'user_id', v_user_id,
    'tenant_id', v_tenant_id,
    'active_store_id', v_active_store_id,
    'active_store_code', v_active_store_code,
    'active_store_display_name', v_active_store_display_name,
    'role', v_role,
    'is_owner', coalesce(v_is_owner, false),
    'permissions', to_jsonb(v_permissions)
  );
end;
$$;

revoke all on function iam.get_session_context(uuid) from public, anon;
revoke all on function iam.bootstrap_owner(uuid, text) from public, anon;
grant execute on function iam.get_session_context(uuid) to authenticated;
grant execute on function iam.bootstrap_owner(uuid, text) to authenticated;
